/// <summary>
/// This class calls METCopyToNewBatchJobsControoler class with current batchjob record buffer
/// </summary>
internal final class METCopyBatchFinRecord_Handler
{
}

Method.Source:
/// <summary>
/// Event handler method for CopyBatchFinRecord
/// </summary>
/// <param name="sender">object that triggered the event.</param>
/// <param name="e">containing event data.</param>
[FormControlEventHandler(formControlStr(BatchJobEnhanced, CopyBatchFinRecord), FormControlEventType::Clicked)]
public static void CopyBatchFinRecord_OnClicked(FormControl sender, FormControlEventArgs e)
{
    FormRun     formRun    = sender.formRun();
    BatchJob    batchJob   = formRun.dataSource(formDataSourceStr(BatchJobEnhanced, BatchJob)).cursor();

    Args args = new Args();
    args.name(menuItemActionStr(METCopyBatchFinRecord));
    args.caller(sender.formRun());
    args.record(batchJob);

    MenuFunction menuFunction = new MenuFunction(args.name(), MenuItemType::Action);
    menuFunction.run(args);
}
